"""Keep header-edit experiments separate from worktree compiler processes."""
import os
from pathlib import Path

ROOTS = (b'/tmp/kin-build-time/', b'/home/bamedeo/kin-wt/build-time/')
BUILD_ROOTS = tuple(b'/mnt/windows/Users/amedeo/Desktop/gamedev/' + name for name in (b'kin-build-time-clang', b'kin-build-time-out', b'kin-build-time-3d-clang'))

def active_compilers():
    found = []
    for process in Path('/proc').iterdir():
        if not process.name.isdigit() or int(process.name) == os.getpid():
            continue
        try:
            arguments = (process / 'cmdline').read_bytes().split(b'\0')
            program = arguments[0].rsplit(b'/', 1)[-1]
            is_compiler = b'clang' in program or program in (b'g++', b'c++', b'cc1plus', b'cc1') or program.endswith(b'-g++')
            is_build_tool = program in (b'ninja', b'ninja-build', b'cmake')
            build_match = False
            if is_build_tool:
                cwd = os.fsencode(os.readlink(process / 'cwd'))
                build_match = any(root in argument for argument in arguments for root in BUILD_ROOTS) or any(cwd.startswith(root) for root in BUILD_ROOTS) or any(root.rstrip(b'/') in argument for argument in arguments for root in ROOTS)
            if (is_compiler and any(root in argument for argument in arguments for root in ROOTS)) or build_match:
                found.append((int(process.name), program.decode(errors='replace')))
        except (FileNotFoundError, PermissionError, ProcessLookupError):
            continue
    return sorted(found)

def assert_no_active_compilers():
    found = active_compilers()
    if found:
        raise RuntimeError(f'Wait for worktree compiler/configure/build processes before experiments: {found}')

